package com.autoops.execution.service;import com.autoops.execution.engine.ExecutionEngine;import com.autoops.execution.entity.Execution;import com.autoops.execution.repository.ExecutionRepository;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.Instant;import java.util.*;@Service public class ExecutionService{private final ExecutionRepository repo;private final ExecutionEngine engine;public ExecutionService(ExecutionRepository r,ExecutionEngine e){repo=r;engine=e;}@Transactional public Execution createCommand(Long user,Long command,List<Long> machines,String mode,int concurrency){if(machines==null||machines.isEmpty())throw new IllegalArgumentException("At least one machine is required");if(concurrency<1||concurrency>3)throw new IllegalArgumentException("Concurrency must be 1-3");var e=new Execution();e.setType("COMMAND");e.setCommandDefinitionId(command);e.setStartedBy(user);e.setMode(mode);e.setConcurrency(concurrency);e.setStatus("PENDING");e.setStartedAt(Instant.now());e=repo.save(e);return e;}public void startResolvedCommand(Long executionId,Long commandId,List<Target> targets,String resolved){var e=repo.findById(executionId).orElseThrow();if(!"PENDING".equals(e.getStatus()))throw new IllegalArgumentException("Execution already started");e.setStatus("RUNNING");repo.save(e);for(var t:targets)engine.runCommand(executionId,commandId,t.machineId(),t.credentialId(),resolved);}public List<Execution> history(Long user){return repo.findByStartedByOrderByIdDesc(user);}public record Target(Long machineId,Long credentialId){} }
